import{J as E,P as w,M as g}from"./index-CxEvVcjn.js";import{T as D}from"./canonicalScripts-BJzxcE-P.js";function H(e,d,n){return e==="es"?n:d}const W={teal:{text:"text-teal-strong",tint:"bg-teal-tint",fill:"bg-teal",border:"border-teal"},coral:{text:"text-coral-strong",tint:"bg-coral-tint",fill:"bg-coral",border:"border-coral"},gold:{text:"text-gold-strong",tint:"bg-gold-tint",fill:"bg-gold",border:"border-gold"},violet:{text:"text-violet-strong",tint:"bg-violet-tint",fill:"bg-violet",border:"border-violet"}};function i(e,d){const n=e.steps.find(h=>h.id===d);if(!n)throw new Error(`pricing.ts has no rung "${d}"`);return n}function a(e){return{id:e.id,label:e.label,labelEs:e.labelEs,amount:e.price,units:e.units}}function V(e){return e.amount/(e.units??1)}function v(e){return e.price/(e.units??1)}const f=i(E,"promo"),y=i(E,"second-free"),t=i(E,"no-gift"),c=i(E,"voucher"),b=i(E,"floor"),q=i(w,"promo"),A=i(w,"creams-free"),S=i(w,"no-scrub"),O=i(w,"voucher"),r=i(g,"b2g1"),x=i(g,"b2g2"),s=i(g,"b1g1"),l=i(g,"floor"),p=E.europeAnchor,u=E.base,T=w.europeAnchor,k=w.base,m=g.europeAnchor,o=g.base,j="Europe Price Anchor",N="Precio Ancla de Europa",$="{locationName} Price",I="Precio de {locationName}";function P(e,d){return[{...a(r),tone:"offer",recommended:!0,words:`"Take any 2 and the third one is free — {currency}${r.price} for ${r.units}. Mix them however you like: ${e}."`,wordsEs:`"Llévate 2 cualesquiera y el tercero es gratis — {currency}${r.price} por ${r.units}. Los mezclas como quieras: ${d}."`},{...a(x),tone:"offer",when:"Only for a group, or at Christmas. Never volunteer it to one person.",whenEs:"Solo para un grupo, o en Navidad. Nunca se lo ofrezcas por tu cuenta a una sola persona.",words:`"We have buy 2 get 1 — but listen, for you I'll do buy 2, get 2. Same {currency}${x.price}, and you walk out with ${x.units}. That is an amazing deal."`,wordsEs:`"Tenemos el compra 2 y llévate 1 — pero mira, para ti lo hago compra 2 y llévate 2. Los mismos {currency}${x.price}, y te llevas ${x.units}. Es un chollo."`},{...a(s),tone:"fallback",when:"They love it but do not need three. Shrink the ask, not the value.",whenEs:"Les encanta pero no necesitan tres. Reduce lo que pides, no el valor.",words:`"My last customer only took one. Let me do something nice for you — buy one, and I'll give you the other one free. I'll staple both receipts together. {currency}${s.price} for ${s.units}."`,wordsEs:`"Mi última clienta se llevó solo uno. Déjame hacerte algo bonito — compra uno y te regalo el otro. Te grapo los dos tickets juntos. {currency}${s.price} por ${s.units}."`}]}const C=[{id:"syringe",accent:"teal",name:"Hyaluronic Acid Syringe (Eye Treatment)",nameEs:"Jeringa de Ácido Hialurónico (Tratamiento de Ojos)",short:"Syringe",shortEs:"Jeringa",europeAnchor:p,base:u,floor:E.floor,rungs:[{id:"anchor",tone:"anchor",label:j,labelEs:N,amount:p,words:`"In our shops in Europe this goes for {currency}${p} — but here in {locationName} we have a much better price for you."`,wordsEs:`"En nuestras tiendas de Europa esto cuesta {currency}${p} — pero aquí en {locationName} tenemos un precio mucho mejor para ti."`},{id:"base",tone:"base",label:$,labelEs:I,amount:u,words:`"Here it is only {currency}${u}."`,wordsEs:`"Aquí son solo {currency}${u}."`},{...a(f),tone:"offer",recommended:!0,words:`"Right now we have an amazing offer — 30% off, so {currency}${f.price} instead of {currency}${u}, and you still choose a gift: Day Cream, Night Cream or the Peeling."`,wordsEs:`"Ahora mismo tenemos una oferta increíble — un 30% de descuento, así que {currency}${f.price} en vez de {currency}${u}, y además eliges un regalo: Crema de Día, Crema de Noche o el Peeling."`},{...a(y),tone:"upsell",words:`"For the same {currency}${y.price} you take two syringes — the second one free for your forehead, upper lip or frown lines. That is {currency}${v(y)} each, with the Day & Night Cream included."`,wordsEs:`"Por los mismos {currency}${y.price} te llevas dos jeringas — la segunda gratis para la frente, el labio superior o las líneas de expresión. Salen a {currency}${v(y)} cada una, con la Crema de Día y de Noche incluidas."`},{...a(t),tone:"fallback",words:`"Let me take the gift out of the deal and I can do {currency}${t.price} for the syringe on its own."`,wordsEs:`"Déjame quitar el regalo y te dejo la jeringa sola en {currency}${t.price}."`},{...a(c),tone:"fallback",when:"Say it while you start her OTHER EYE — hands busy, face tilted up. One voucher, once. There is no second one.",whenEs:"Dilo mientras le empiezas el OTRO OJO — manos ocupadas, cara hacia arriba. Un cupón, una vez. No hay un segundo.",words:`"You know what, let me fix your other eye real quick. [start it] … Listen, I have a 20% voucher here and I'll do it for you. But you are being greedy now, eh? {currency}${t.price} down to {currency}${c.price} — the syringe on its own, no gift, and only while you are sitting in front of me."`,wordsEs:`"¿Sabes qué? Déjame arreglarte el otro ojo rapidito. [empieza] … Mira, tengo aquí un cupón del 20% y te lo hago. Pero qué morro tienes, ¿eh? De {currency}${t.price} a {currency}${c.price} — la jeringa sola, sin regalo, y solo mientras estés aquí sentada delante de mí."`},{...a(b),tone:"floor",when:"NOT YOURS TO GIVE. Full market, then call the manager — he says the number, not you.",whenEs:"NO ES TUYO. Mercado puro, y llamas al encargado — el número lo dice él, no tú.",words:`"Give me ten seconds, I'll see what I can do for you." [Go and get the manager.] {currency}${b.price} is the lowest this ever goes and it comes out of his mouth, not yours. Never under it, and never without him.`,wordsEs:`"Dame diez segundos, a ver qué puedo hacer por ti." [Ve a por el encargado.] {currency}${b.price} es lo más bajo a lo que llega esto y sale de su boca, no de la tuya. Nunca por debajo, y nunca sin él.`}],proof:{label:"Proof move — one eye only, and the other one is the close",labelEs:"Prueba — solo un ojo, y el otro es el cierre",words:`"Let me do one eye only — then you hold the mirror and tell me if you see the difference." You never do the second one for free: it comes out at {currency}${t.price} as the cover for the voucher, or after she has paid.`,wordsEs:`"Déjame hacerte solo un ojo — luego coges el espejo y me dices si ves la diferencia." El segundo no es gratis nunca: sale a {currency}${t.price} como tapadera del cupón, o cuando ya ha pagado.`}},{id:"peeling",accent:"violet",name:"Glycolic Peeling",nameEs:"Peeling Glicólico",short:"Peeling",shortEs:"Peeling",europeAnchor:T,base:k,floor:w.floor,rungs:[{id:"anchor",tone:"anchor",label:j,labelEs:N,amount:T,words:`"In Europe this treatment costs {currency}${T}."`,wordsEs:`"En Europa este tratamiento cuesta {currency}${T}."`},{id:"base",tone:"base",label:$,labelEs:I,amount:k,words:`"Here in {locationName} it is only {currency}${k}."`,wordsEs:`"Aquí en {locationName} son solo {currency}${k}."`},{...a(q),tone:"offer",recommended:!0,words:`"This is not an anti-ageing cream — it lifts the dead skin off the living skin. Today it is half the Europe price, {currency}${q.price}, and the Dead Sea Body Scrub comes free with it."`,wordsEs:`"Esto no es una crema antiedad — separa la piel muerta de la piel viva. Hoy está a mitad del precio de Europa, {currency}${q.price}, y el Exfoliante del Mar Muerto va de regalo."`},{...a(A),tone:"upsell",words:`"For the full {currency}${A.price} you keep the peeling and the Day & Night Cream come free — that is the complete routine."`,wordsEs:`"Por los {currency}${A.price} completos te quedas el peeling y la Crema de Día y de Noche van gratis — esa es la rutina completa."`},{...a(S),tone:"fallback",words:`"If you do not need the scrub I will take it back as credit — the scrub is {currency}${l.price}, so that leaves the peeling at {currency}${S.price}."`,wordsEs:`"Si no necesitas el exfoliante te lo descuento como crédito — el exfoliante son {currency}${l.price}, así que el peeling se queda en {currency}${S.price}."`},{...a(O),tone:"floor",words:`"With today's voucher a single peeling is {currency}${O.price} — no gifts at that price, and that is as low as it goes."`,wordsEs:`"Con el cupón de hoy un peeling solo son {currency}${O.price} — sin regalos a ese precio, y de ahí no baja."`}],proof:{label:"Proof move — the hand test",labelEs:"Prueba — la prueba de la mano",words:'"Watch my hand — sixty seconds, and you will see five years of dullness come off."',wordsEs:'"Mira mi mano — sesenta segundos, y verás cómo se va la opacidad de cinco años."'}},{id:"scrub",accent:"gold",name:"Dead Sea Scrub & Body Butter",nameEs:"Exfoliante del Mar Muerto y Manteca Corporal",short:"Scrub",shortEs:"Exfoliante",europeAnchor:m,base:o,floor:g.floor,perUnit:!0,rungs:[{id:"anchor",tone:"anchor",label:j,labelEs:N,amount:m,perUnit:!0,words:`"In Europe each of these is {currency}${m} — here in {locationName} they are {currency}${o} each."`,wordsEs:`"En Europa cada uno de estos cuesta {currency}${m} — aquí en {locationName} son {currency}${o} cada uno."`},{id:"base",tone:"base",label:$,labelEs:I,amount:o,perUnit:!0,words:`"One jar on its own is {currency}${o} — but nobody takes just one once they hear the offer."`,wordsEs:`"Un bote solo son {currency}${o} — pero nadie se lleva uno solo cuando oye la oferta."`},...P("scrub, body butter, even a Nail Kit","exfoliante, manteca corporal, incluso un Kit de Uñas"),{...a(l),tone:"floor",when:"Only when you can SEE they love it — they have not stopped touching their hands.",whenEs:"Solo cuando VES que les encanta — no paran de tocarse las manos.",words:`"You really love it, don't you — you haven't stopped touching your hands. Alright: {currency}${l.price} for the one. But zip it, this stays between us."`,wordsEs:`"Te encanta de verdad, ¿eh? No paras de tocarte las manos. Venga: {currency}${l.price} por uno. Pero chitón, que esto queda entre nosotros."`}],proof:{label:"Proof move — the flip test",labelEs:"Prueba — la prueba del vuelco",words:'"Watch — I turn the jar upside down and nothing falls out. That is how dense the butter is."',wordsEs:'"Mira — le doy la vuelta al bote y no se cae nada. Así de densa es la manteca."'}},{id:"nailkit",accent:"coral",name:"French Nail Kit",nameEs:"Kit de Uñas Francesas",short:"Nail Kit",shortEs:"Kit de Uñas",europeAnchor:m,base:o,floor:g.floor,rungs:[{id:"anchor",tone:"anchor",label:j,labelEs:N,amount:m,words:`"In Europe this nail kit is {currency}${m} — here in {locationName} it is {currency}${o}."`,wordsEs:`"En Europa este kit de uñas cuesta {currency}${m} — aquí en {locationName} son {currency}${o}."`},{id:"base",tone:"base",label:$,labelEs:I,amount:o,words:`"The complete kit — file, tips, gel, everything — is {currency}${o}."`,wordsEs:`"El kit completo — lima, tips, gel, todo — son {currency}${o}."`},...P("three kits, or a kit with a Scrub and a Body Butter","tres kits, o un kit con un Exfoliante y una Manteca Corporal"),{...a(l),tone:"floor",when:"Only when you can SEE they love it. This is the last price, not an opener.",whenEs:"Solo cuando VES que les encanta. Es el último precio, no una apertura.",words:`"The whole kit for {currency}${l.price} — that is my final price. But zip it, this stays between us."`,wordsEs:`"El kit entero por {currency}${l.price} — ese es mi precio final. Pero chitón, que esto queda entre nosotros."`}],proof:{label:"Proof move — the guarantee",labelEs:"Prueba — la garantía",words:'"Even if your dog eats it, bring it back and we replace it."',wordsEs:'"Aunque se lo coma tu perro, lo traes y te lo cambiamos."'}}],Y={syringe:C[0],peeling:C[1],scrub:C[2],nailkit:C[3]},L=[{id:"o-ready",category:"opening",title:"1. Before anybody comes",titleEs:"1. Antes de que venga nadie",text:"Stand where they can see you, sample already in your hand. Not flat against the wall, not planted in the middle of the walkway blocking people. Ready before you need to be ready.",textEs:"Colócate donde te vean, con la muestra ya en la mano. Ni pegado a la pared, ni plantado en mitad del paso cortándole el camino a la gente. Listo antes de que haga falta."},{id:"o-look",category:"opening",title:"2. Get the look before you move",titleEs:"2. Consigue la mirada antes de moverte",text:'Four or five metres out, while they are still walking: "Hi guys, how you doing?" — and WAIT. Do not step, do not raise the sample. Only once they look at you do you lift it and start walking towards them.',textEs:'A cuatro o cinco metros, cuando todavía vienen andando: "Hola chicos, ¿qué tal?" — y ESPERA. No des un paso, no levantes la muestra. Solo cuando te miren la levantas y empiezas a andar hacia ellos.'},{id:"o-coin",category:"opening",title:"3. The sample is a coin toss",titleEs:"3. La muestra es cara o cruz",text:"They take it, lovely. They wave it away, nothing happens — you never asked them for anything, so you have not been rejected. Either way you are still stood in front of them and you go straight into the next line.",textEs:"Si la cogen, genial. Si la apartan con la mano, no pasa nada — no les has pedido nada, así que no te han rechazado. En los dos casos sigues plantado delante de ellos y vas directo a la frase siguiente."},{id:"o-rush",category:"opening",title:"4. Name the rush before they can",titleEs:"4. Nombra la prisa antes que ellos",...D},{id:"o-gift",category:"opening",title:"5. The gift, then turn and walk",titleEs:"5. El regalo, y date la vuelta",text:`"Really? No way. You know what — just because you look so amazing, I'm going to give you a small gift. I think you're going to love it." Then turn and walk into the shop. Do NOT look back to see if they follow.`,textEs:'"¿En serio? No me lo creo. ¿Sabes qué? Solo porque estás guapísima, te voy a hacer un regalito. Creo que te va a encantar." Luego date la vuelta y entra en la tienda. NO mires atrás para ver si te siguen.'},{id:"o-come",category:"opening",title:"6. Only now, look back",titleEs:"6. Ahora sí, mira atrás",text:`Once you are inside, turn your head. If they are still on the pavement: "Come on guys, it's two seconds, I promise. Come." Then turn back round and keep walking.`,textEs:'Una vez dentro, gira la cabeza. Si siguen en la acera: "Venga chicos, son dos segundos, os lo prometo. Venid." Y date la vuelta otra vez y sigue andando.'},{id:"o-doorway",category:"opening",title:"7. Never wait in the doorway",titleEs:"7. Nunca te quedes esperando en la puerta",text:"Say it, turn, walk — the walking is what persuades, because now there is nothing to say no to. Do not stand there watching them decide, and never walk them in beside you. You go first and you call them to come.",textEs:"Lo dices, te giras, andas — lo que convence es el andar, porque ya no hay nada a lo que decir que no. No te quedes ahí mirando cómo lo deciden, y nunca los metas andando a tu lado. Vas tú delante y los llamas."},{id:"o-seat",category:"opening",title:"8. Sit them facing the wall",titleEs:"8. Siéntalos mirando a la pared",text:"Put them in the chair facing INTO the shop, never facing the street. If they can see the pavement moving, they start thinking about being back on it.",textEs:"Siéntalos mirando HACIA DENTRO de la tienda, nunca hacia la calle. Si ven el movimiento de la acera, empiezan a pensar en volver a ella."},{id:"o-group",category:"opening",title:"9. Count the heads before you start",titleEs:"9. Cuenta las cabezas antes de empezar",text:`THREE OR FEWER: do all of them. FOUR OR MORE: "I just need ONE of you to try this — who's the bravest?" One volunteer, and you only open it up to the rest if you can SEE real excitement. Let the others watch and want a turn — that is what makes them buy.`,textEs:'TRES O MENOS: se lo haces a todas. CUATRO O MÁS: "solo necesito que lo pruebe UNA — ¿quién es la más valiente?" Una voluntaria, y solo abres al resto si VES entusiasmo de verdad. Que las demás miren y les entren ganas — eso es lo que hace que compren.'},{id:"o1",category:"opening",product:"syringe",title:"Straight in, no warm-up",titleEs:"Directo, sin calentar",text:'"Can I show you something? This is our bestselling treatment — it is like Botox in a syringe, but natural and instant."',textEs:'"¿Puedo enseñarte una cosa? Este es nuestro tratamiento más vendido — es como Botox en una jeringa, pero natural e instantáneo."'},{id:"o2",category:"opening",product:"syringe",title:"Say the nice thing first",titleEs:"Di lo bonito primero",text:'"Your skin has great structure. I want to show you something that takes it to the next level — our instant filler treatment."',textEs:'"Tu piel tiene una estructura estupenda. Quiero enseñarte algo que la lleva al siguiente nivel — nuestro tratamiento de relleno instantáneo."'},{id:"o3",category:"opening",product:"peeling",title:"Name the thing she already sees",titleEs:"Nombra lo que ella ya ve",text:'"Do you ever feel like your skin looks dull even with makeup on? Our 60-second peeling fixes that instantly."',textEs:'"¿Alguna vez notas la piel apagada incluso con maquillaje? Nuestro peeling de 60 segundos lo arregla al instante."'},{id:"o4",category:"opening",product:"peeling",title:"The Reveal",titleEs:"La Revelación",text:'"I am going to show you something — watch my hand. See the difference? That is five years of dullness gone in one minute."',textEs:'"Te voy a enseñar una cosa — mira mi mano. ¿Ves la diferencia? Eso son cinco años de opacidad fuera en un minuto."'},{id:"o5",category:"opening",product:"scrub",title:"Spa Experience",titleEs:"Experiencia de Spa",text:'"Close your eyes for a second... smell that? Those are Dead Sea minerals. Let me give you the 30-second spa experience."',textEs:'"Cierra los ojos un segundo... ¿hueles eso? Son minerales del Mar Muerto. Déjame darte la experiencia de spa de 30 segundos."'},{id:"o6",category:"opening",product:"nailkit",title:"Time Saver",titleEs:"Ahorro de Tiempo",text:'"How often do you get a French manicure? What if you could do it at home in 5 minutes, perfect every time?"',textEs:'"¿Cada cuánto te haces la manicura francesa? ¿Y si pudieras hacértela en casa en 5 minutos, perfecta siempre?"'},{id:"o7",category:"opening",title:"Universal — Direct",titleEs:"Universal — Directo",text:'"I have something I want to show you — it takes 30 seconds and you will see an instant difference."',textEs:'"Tengo una cosa que quiero enseñarte — son 30 segundos y verás una diferencia al instante."'},{id:"o8",category:"opening",title:"Universal — Gift Angle",titleEs:"Universal — Ángulo de Regalo",text:'"Are you shopping for anyone else today? Because this makes the perfect gift — and I will show you why."',textEs:'"¿Estás comprando para alguien más hoy? Porque esto es el regalo perfecto — y te enseño por qué."'},{id:"c-card",category:"closing",title:"Assume the card",titleEs:"Da por hecho la tarjeta",text:`"I guess you're paying by card, aren't you? Visa or Mastercard?" Most people pay by card, so assume it — you are asking WHICH, never WHETHER.`,textEs:'"Supongo que pagas con tarjeta, ¿no? ¿Visa o Mastercard?" La mayoría paga con tarjeta, así que dalo por hecho — preguntas CUÁL, nunca SI.'},{id:"c-no-silence",category:"closing",title:"Do not go quiet after the ask",titleEs:"No te calles después de pedir",text:`They say "I don't know… Visa." You say: "Perfect, don't worry — I'll bring it over to you." Then go and get the machine. You never leave them alone with the decision.`,textEs:'Dicen "no sé... Visa." Tú dices: "Perfecto, no te preocupes — te la traigo yo." Y vas a por el datáfono. Nunca los dejas solos con la decisión.'},{id:"c-on-the-spot",category:"closing",title:"Charge where they are sitting",titleEs:"Cobra donde están sentados",text:"The machine comes to the customer. Never walk them to a till — every metre between the yes and the payment is a metre they can change their mind in.",textEs:"El datáfono va al cliente. Nunca los lleves a la caja — cada metro entre el sí y el pago es un metro para que cambien de opinión."},{id:"c1",category:"closing",product:"syringe",title:"Two-Choice Close",titleEs:"Cierre de Dos Opciones",text:`"So would you rather take the single syringe at {currency}${u}, or two syringes at {currency}${y.price} with the second one free for your forehead or upper lip?"`,textEs:`"Entonces, ¿prefieres la jeringa sola a {currency}${u}, o dos jeringas a {currency}${y.price} con la segunda gratis para la frente o el labio superior?"`},{id:"c1b",category:"closing",product:"syringe",title:"Two-Choice Close (Offer)",titleEs:"Cierre de Dos Opciones (Oferta)",text:`"Would you rather have 30% off at {currency}${f.price} with a free gift, or the two-syringe deal at {currency}${y.price}?"`,textEs:`"¿Prefieres el 30% de descuento a {currency}${f.price} con un regalo, o la oferta de dos jeringas a {currency}${y.price}?"`},{id:"c2",category:"closing",title:"Assumptive Close",titleEs:"Cierre Asumido",text:`"Right — I'm wrapping this one up for you. Gift bag, or straight in the bag?" You are not asking whether. You are asking which.`,textEs:'"Venga — te lo envuelvo ya. ¿Con bolsa de regalo o tal cual?" No preguntas si lo quiere. Preguntas qué bolsa.'},{id:"c3",category:"closing",title:"Scarcity Close",titleEs:"Cierre de Escasez",text:'"This voucher price is only valid today — I do not want you to miss it. Shall I ring it up?"',textEs:'"Este precio con cupón solo vale hoy — no quiero que lo pierdas. ¿Te lo cobro?"'},{id:"c4",category:"closing",product:"syringe",title:"Summary Close",titleEs:"Cierre de Resumen",text:`"So you are getting a treatment that costs {currency}${p} in Europe for {currency}${u} here in {locationName}. Great choice."`,textEs:`"O sea que te llevas un tratamiento que en Europa cuesta {currency}${p} por {currency}${u} aquí en {locationName}. Gran elección."`},{id:"c4b",category:"closing",product:"syringe",title:"Summary Close (Offer)",titleEs:"Cierre de Resumen (Oferta)",text:`"So you are getting the treatment at 30% off — {currency}${f.price} — plus a gift on top. The Peeling on its own is {currency}${k}."`,textEs:`"O sea que te llevas el tratamiento con un 30% de descuento — {currency}${f.price} — y encima un regalo. El Peeling solo cuesta {currency}${k}."`},{id:"c5",category:"closing",title:"Testimonial Close",titleEs:"Cierre con Testimonio",text:'"A customer was in here yesterday — she bought two, and came back today for three more as gifts. That is how good this is."',textEs:'"Ayer estuvo aquí una clienta — se llevó dos, y hoy ha vuelto a por tres más para regalar. Así de bueno es."'},{id:"c-second-eye",category:"closing",product:"syringe",title:`The other eye — say it to close, at {currency}${t.price}`,titleEs:`El otro ojo — dilo para cerrar, a {currency}${t.price}`,text:`She is at {currency}${t.price} and about to stand up. "You know what, let me fix your other eye real quick." [Start it. Do NOT let her stand.] And while your hands are on her face: "Listen, I just checked something — this little 20% voucher brings it to {currency}${c.price}. But you're being greedy, eh? Single syringe only." The price moves inside a moment that is about her face.`,textEs:`Está en {currency}${t.price} y a punto de levantarse. "¿Sabes qué? Déjame arreglarte el otro ojo rapidito." [Empieza. NO dejes que se levante.] Y con las manos en su cara: "Mira, acabo de comprobar una cosa — este cuponcito del 20% lo deja en {currency}${c.price}. Pero qué morro tienes, ¿eh? Solo la jeringa sola." El precio se mueve dentro de un momento que va de su cara.`},{id:"c-second-eye-asked",category:"closing",product:"syringe",title:"She asks for the other eye BEFORE buying",titleEs:"Te pide el otro ojo ANTES de comprar",text:`Do not refuse it and do not hand it over. Condition it: "If you buy it, I'll do the other one, yeah?" She pays, she gets it done, no argument and no theatre. The untouched eye is your best argument — you never give your best argument away to a maybe.`,textEs:'Ni le digas que no ni se lo regales. Ponle condición: "Si te lo llevas, te hago el otro, ¿vale?" Si paga, se lo haces, sin discusión y sin teatro. El ojo sin tocar es tu mejor argumento — tu mejor argumento no se lo regalas a un quizá.'},{id:"c-handover",category:"closing",product:"syringe",title:"She paid — now hand her over (do NOT sell again)",titleEs:"Ha pagado — ahora la traspasas (NO le vendas otra vez)",text:`While she is still sitting down: "There's a guy here, a specialist — he's only with us a short time and honestly he's amazing at what he does. And just because you got this, I'm going to spoil you with a small gift. Tell me one thing: what's more important for you if you could get it lifted — the cheeks, or the neck? … Would that make you happy? Let me check with him, if you have one second." Then YOU walk and fetch him. She never stands up, you never price his product, and you never pitch a second one of yours.`,textEs:'Con ella todavía sentada: "Aquí hay un chico, un especialista — está poco tiempo con nosotros y de verdad, es un crack en lo suyo. Y solo porque te has llevado esto, te voy a mimar con un regalito. Dime una cosa: ¿qué es más importante para ti si pudieras levantarlo — los pómulos o el cuello? … ¿Eso te haría feliz? Déjame consultarlo con él, si tienes un segundo." Y vas TÚ a buscarlo. Ella no se levanta, tú no le pones precio a lo suyo, y no le sueltas un segundo producto tuyo.'},{id:"r-stall",category:"objection",answers:"think",title:'"I need to think about it" — the real answer',titleEs:'"Me lo tengo que pensar" — la respuesta de verdad',text:`"What do you actually need to think about? You already told me you like it. You told me you'd use it. You're not going to walk up and down the street and come back to a different price — you know exactly what it does. It's just whether you want to treat yourself or not. It's not a mortgage."`,textEs:'"¿Qué te tienes que pensar exactamente? Ya me has dicho que te gusta. Me has dicho que lo usarías. No vas a dar una vuelta por la calle y volver con otro precio — sabes perfectamente lo que hace. Es simplemente si quieres darte un capricho o no. Tampoco es una hipoteca."'},{id:"r-trust",category:"objection",answers:"trust",title:'"I was scammed before"',titleEs:'"Ya me han timado antes"',text:`"I am SO sorry that happened to you. There are some bad people out there, and it makes my job harder because guys like that ruin it for everyone. Look — I won't ask you to trust me. Let me just show you how this works, and YOU decide. No pressure, no strings."`,textEs:'"Siento muchísimo que te pasara eso. Hay gente muy mala por ahí, y a mí me complica el trabajo porque tipos así lo estropean para todos. Mira — no te voy a pedir que confíes en mí. Déjame enseñarte cómo funciona y decides TÚ. Sin presión, sin compromiso."'},{id:"r-skin",category:"objection",answers:"skin",title:'"Will this work on my skin?"',titleEs:'"¿Esto funciona en mi piel?"',text:`"Great question! This is hyaluronic acid — it's a water molecule, not a bleach. It doesn't care about skin colour. It works by binding water under your skin. Your melanin stays exactly the same. You just get smoother, plumper skin. Want me to show you on my hand?"`,textEs:'"¡Muy buena pregunta! Esto es ácido hialurónico — es una molécula de agua, no un blanqueador. Le da igual el tono de piel. Funciona reteniendo agua bajo la piel. Tu melanina se queda exactamente igual. Solo consigues una piel más lisa y con más volumen. ¿Te lo enseño en mi mano?"'},{id:"r-skin-sensitive",category:"objection",answers:"skin",title:'"It will not suit my skin"',titleEs:'"No le va a ir bien a mi piel"',text:'"Nothing to worry about, my love. All natural — no chemicals, no parabens, nothing in there to upset anybody. The most sensitive skin in the world can take this. I have had women use it going through the worst treatment you can imagine, when they could not put a drop of anything else on their face. And this is not another moisturiser you slap on every morning — completely different thing, once a week. Once. Give me your hand."',textEs:'"No tienes nada de qué preocuparte, cariño. Todo natural — sin químicos, sin parabenos, nada que le pueda molestar a nadie. La piel más sensible del mundo aguanta esto. He tenido a mujeres usándolo mientras pasaban por el peor tratamiento que te puedas imaginar, cuando no se podían poner ni una gota de nada más en la cara. Y esto no es otra crema para ponerte cada mañana — es otra cosa completamente distinta, una vez a la semana. Una. Dame la mano."'},{id:"c-two-yeses",category:"closing",title:"The two yeses (ask during the demo)",titleEs:"Los dos síes (pregúntalos durante la demo)",text:'"Do you like it? … Yes? And if you had it at home, would you actually use it? … Yes?" [Now there is nothing left to argue about except the price.]',textEs:'"¿Te gusta? … ¿Sí? Y si lo tuvieras en casa, ¿lo usarías de verdad? … ¿Sí?" [Ahora ya no queda nada que discutir salvo el precio.]'},{id:"r-online",category:"objection",answers:"online",title:'"I can get it cheaper online"',titleEs:'"Lo consigo más barato online"',text:`"Maybe — but here's the thing about skincare online. Counterfeits are everywhere: fake, expired, or diluted. This?" [hold up the sealed product] "Sealed, fresh, straight from the manufacturer. And you just watched it work on your own face. Can a website do that?"`,textEs:'"Puede ser — pero te cuento cómo va la cosmética por internet. Está lleno de falsificaciones: producto falso, caducado o diluido. ¿Esto?" [enseña el producto precintado] "Precintado, fresco, directo del fabricante. Y lo acabas de ver funcionar en tu propia cara. ¿Eso te lo hace una web?"'},{id:"p-his-turn",category:"objection",answers:"partner",title:"Ask my partner — his turn",titleEs:"Consultar pareja — le toca a él",text:'"Let me ask you something, my love. When he bought his last pair of golf shoes — did he ring you first?" [Wait for the laugh.] "There you go. Your face, your money, your call."',textEs:'"Déjame preguntarte una cosa, cariño. Cuando se compró las últimas zapatillas de golf — ¿te llamó a ti antes?" [Espera la risa.] "Pues eso. Tu cara, tu dinero, tú decides."'},{id:"p-he-notices-you",category:"objection",answers:"partner",title:"Ask my partner — he notices you, not the receipt",titleEs:"Consultar pareja — te mira a ti, no al ticket",text:'"He is not going to notice the receipt, darling. He is going to notice you on Saturday. I have never once had a man come back and complain that his wife looks too good."',textEs:'"Cariño, él no se va a fijar en el ticket. Se va a fijar en ti el sábado. Nunca en la vida me ha venido un hombre a quejarse de que su mujer esté demasiado guapa."'},{id:"t-do-not-trust-me",category:"objection",answers:"trust",title:"Been scammed — do not trust me",titleEs:"Ya me han timado — no te fíes de mí",text:'"Then do not trust me. Seriously — do not. Trust your own hand. Give it here, thirty seconds, and you tell ME what you think. If nothing happens, I have wasted my time and you have lost nothing."',textEs:'"Pues no te fíes de mí. En serio — no te fíes. Fíate de tu mano. Dámela, treinta segundos, y me dices TÚ qué te parece. Si no pasa nada, he perdido yo el tiempo y tú no has perdido nada."'},{id:"t-not-a-story",category:"objection",answers:"trust",title:"Been scammed — I am not telling you a story",titleEs:"Ya me han timado — yo no te cuento cuentos",text:'"Whoever did that to you was selling you a story. I am not telling you a story — I am putting it on your hand and you are watching it happen with your own eyes. That is a very different thing."',textEs:'"Quien te hizo eso te estaba vendiendo un cuento. Yo no te cuento nada — te lo pongo en la mano y lo ves pasar con tus propios ojos. Eso es muy distinto."'},{id:"s-it-would-argue-now",category:"objection",answers:"skin",title:"Wrong for my skin — it would argue right now",titleEs:"No es para mi piel — lo notarías ahora mismo",text:'"If your skin was going to argue with it, my love, it would argue right now — on the back of your hand, in front of me. That is the whole test. Give it here."',textEs:'"Cariño, si tu piel le fuera a poner pegas, se las pondría ahora mismo — en el dorso de la mano, delante de mí. Ese es el test entero. Dámela."'},{id:"s-what-are-you-using",category:"objection",answers:"skin",title:"Wrong for my skin — what are you on now?",titleEs:"No es para mi piel — ¿y qué usas ahora?",text:'"What are you using now, my love?" [Listen properly.] "Right. And how is that going for you? Look — this is not the same kind of thing at all. It is once a week, and it is not fighting with anything else you put on."',textEs:'"¿Y qué usas ahora, cariño?" [Escucha de verdad.] "Ya. ¿Y qué tal te va? Mira — esto no es lo mismo ni de lejos. Es una vez a la semana, y no se pelea con nada de lo que ya te pongas."'},{id:"o-you-felt-it",category:"objection",answers:"online",title:"Cheaper online — you cannot feel a photograph",titleEs:"Más barato online — una foto no se toca",text:'"You can buy a photograph of it online, my darling. What you cannot buy online is the thing you just felt on your own hand. You already know this one works. That is worth more than a delivery date."',textEs:'"Online te puedes comprar una foto, cariño. Lo que no te puedes comprar online es lo que acabas de notar en tu propia mano. Ya sabes que este funciona. Eso vale más que una fecha de entrega."'},{id:"o-tonight-not-next-week",category:"objection",answers:"online",title:"Cheaper online — tonight, not next week",titleEs:"Más barato online — esta noche, no la semana que viene",text:'"And then you wait a week for a bag from who knows where. You are here, it is here, and you could be using it tonight. Do not make yourself wait for something you have already decided you like."',textEs:'"Y luego te pasas una semana esperando un paquete de vete a saber dónde. Tú estás aquí, esto está aquí, y lo podrías estar usando esta noche. No te hagas esperar por algo que ya has decidido que te gusta."'},{id:"ti-coffee",category:"objection",answers:"time",title:"No time — shorter than choosing a coffee",titleEs:"Sin tiempo — menos que pedir un café",text:'"Sixty seconds, my love. You spent longer than that deciding what coffee to order. One hand — go on."',textEs:'"Sesenta segundos, cariño. Has tardado más en decidir qué café pedir. Una mano — venga."'},{id:"ti-i-will-let-you-go",category:"objection",answers:"time",title:"No time — I will let you go myself",titleEs:"Sin tiempo — te suelto yo mismo",text:'"I am not going to keep you, I promise. One hand, thirty seconds, and if it does nothing for you I will let you go myself. Fair enough?"',textEs:'"Que no te entretengo, te lo prometo. Una mano, treinta segundos, y si no te dice nada te suelto yo mismo. ¿Trato hecho?"'},{id:"l-touching-is-free",category:"objection",answers:"looking",title:"Just looking — touching is free too",titleEs:"Solo mirando — tocar también es gratis",text:'"Looking is free, gorgeous. Touching is free as well. Come here — give me the hand and then you can carry on looking."',textEs:'"Mirar es gratis, guapa. Tocar también. Ven — dame la mano y luego sigues mirando."'},{id:"r1",answers:"think",category:"objection",title:'"I need to think about it"',titleEs:'"Necesito pensármelo"',text:'"Think about what, my love? You told me you like it. You told me you would use it. So it is the price — say it out loud and let me see what I can do for you. Because the second you walk out of here this price is gone, and I cannot get it back for you tomorrow."',textEs:'"¿Pensar el qué, cariño? Me has dicho que te gusta. Me has dicho que lo usarías. Entonces es el precio — dilo en voz alta y veo qué puedo hacer por ti. Porque en cuanto salgas por esa puerta este precio ya no existe, y mañana no te lo puedo recuperar."'},{id:"r2",answers:"price",category:"objection",product:"syringe",title:'"It is too expensive"',titleEs:'"Es muy caro"',text:`[You are not at the top of the ladder when you hear this — say the number you are actually on] "Too expensive next to what, my love? You are at {currency}${t.price} already — gift off, the syringe on its own. [Now start her other eye — "let me fix your other eye real quick" — and talk money with your hands on her face] Tell you what. I have a 20% voucher here and I am going to put it on you. But you are being greedy now, eh? {currency}${c.price}. Sixty goes in that syringe, one a week, all the way to next summer — a bit over {currency}2 a time. And it dies the second you walk out of that door."`,textEs:`[Cuando oyes esto ya no estás arriba de la escalera — di el número en el que estás de verdad] "¿Caro comparado con qué, cariño? Si ya estás en {currency}${t.price} — sin regalo, la jeringa sola. [Ahora empiézale el otro ojo — "déjame arreglarte el otro ojo rapidito" — y habla de dinero con las manos en su cara] Mira lo que voy a hacer. Tengo aquí un cupón del 20% y te lo pongo. Pero qué morro tienes, ¿eh? {currency}${c.price}. Sesenta usos en esa jeringa, uno por semana, hasta el verano que viene — poco más de {currency}2 cada vez. Y se muere en cuanto cruces esa puerta."`},{id:"r2b",answers:"price",category:"objection",product:"peeling",title:'"It is too expensive"',titleEs:'"Es muy caro"',text:`[Not the shelf price — the rung you are on] "You are at {currency}${q.price} already, gorgeous, with the Dead Sea scrub going in the bag with it. So listen: if the scrub is not for you I take it straight back as credit — that is {currency}${l.price} off — and the peeling on its own is {currency}${S.price}. Same bottle, same year of Sunday nights. Shall I wrap it?"`,textEs:`[No el precio de la estantería — el escalón en el que estás] "Ya estás en {currency}${q.price}, guapa, con el exfoliante del Mar Muerto metido en la bolsa. Así que mira: si el exfoliante no es para ti te lo descuento como crédito — {currency}${l.price} menos — y el peeling solo se queda en {currency}${S.price}. El mismo bote, el mismo año entero. ¿Te lo envuelvo?"`},{id:"r2c",answers:"price",category:"objection",product:"scrub",title:'"It is too expensive"',titleEs:'"Es muy caro"',text:`"You are haggling with me over a jar, my love. Look — one on its own is {currency}${o}, and I am not going to make you pay that for one. Buy one, get one: two of them, {currency}${s.price}. One for you, one for whoever you like — {currency}${v(s)} each, and you have not stopped touching your hands since I put it on them." [She only wants ONE and she is genuinely leaving? Then {currency}${l.price} for the single — same money per jar, one jar out of the door instead of two. That is why you try this one first.]`,textEs:`"Me estás regateando por un bote, cariño. Mira — uno solo son {currency}${o}, y no te voy a cobrar eso por uno. Compra uno y llévate otro: dos, {currency}${s.price}. Uno para ti y otro para quien tú quieras — {currency}${v(s)} cada uno, y no paras de tocarte las manos desde que te lo puse." [¿Solo quiere UNO y se está yendo de verdad? Entonces {currency}${l.price} el individual — el mismo dinero por bote, pero sale uno por la puerta en vez de dos. Por eso esta la pruebas primero.]`},{id:"r2d",answers:"price",category:"objection",product:"nailkit",title:'"It is too expensive"',titleEs:'"Es muy caro"',text:`"For everything that is in that box? One kit on its own is {currency}${o} — and I am not asking you for that. Take the kit and put a Scrub next to it, buy one get one, the pair of them {currency}${s.price}. That is {currency}${v(s)} each and the buffer is guaranteed for life — break it, wear it out, bring it back, we swap it. Who is the second one for?"`,textEs:`"¿Por todo lo que lleva esa caja? Un kit solo son {currency}${o} — y no te lo voy a cobrar. Coge el kit y ponle un Exfoliante al lado, compra uno y llévate otro, los dos por {currency}${s.price}. Salen a {currency}${v(s)} cada uno y la lima tiene garantía de por vida — se rompe, se gasta, la traes y te la cambiamos. ¿Para quién es el segundo?"`},{id:"r3",category:"objection",title:'"I already have something similar"',titleEs:'"Ya tengo algo parecido"',text:'"Most of our customers do too. But when they try this they tell me it is completely different. Can I show you why in 30 seconds?"',textEs:'"La mayoría de nuestros clientes también. Pero cuando lo prueban me dicen que es completamente distinto. ¿Te enseño por qué en 30 segundos?"'},{id:"r-breaks",category:"objection",product:"nailkit",title:'"What if it breaks?"',titleEs:'"¿Y si se rompe?"',text:'"The buffer has a lifetime warranty. No matter what happens — if it breaks, if it wears out, even if your dog eats it — you can exchange it in any of our stores worldwide." [Let them laugh — humour lowers the guard. Say it with total confidence: this one is real.]',textEs:'"La lima tiene garantía de por vida. No importa qué pase — si se rompe, si se desgasta, incluso si tu perro se la come — puedes cambiarla en cualquiera de nuestras tiendas en todo el mundo." [Déjales reír — el humor baja la guardia. Dilo con total confianza: esta va en serio.]'},{id:"r4",answers:"looking",category:"objection",title:'"I am just looking"',titleEs:'"Solo estoy mirando"',text:'"No problem at all — looking is free. But can I show you something that takes 20 seconds? You do not have to buy anything, I just love the reaction."',textEs:'"No pasa nada — mirar es gratis. Pero ¿te enseño una cosa de 20 segundos? No tienes que comprar nada, es que me encanta la reacción."'},{id:"r5",answers:"partner",category:"objection",title:'"I need to ask my partner"',titleEs:'"Tengo que preguntarle a mi pareja"',text:`"Ladies' business, my darling. He is playing golf — he is not thinking about your face. You told me you like it. You told me you would use it. So it is your call, not his. Spoil yourself for once. And if you really would not use it, keep your money — no hard feelings, it is all good."`,textEs:'"Cosa de mujeres, cariño. Él está con el golf — no está pensando en tu cara. Me has dicho que te gusta. Me has dicho que lo usarías. Así que es cosa tuya, no suya. Date un capricho por una vez. Y si de verdad no lo vas a usar, guárdate el dinero — sin rencores, no pasa nada."'},{id:"r6",answers:"time",category:"objection",title:'"I do not have time"',titleEs:'"No tengo tiempo"',text:'"This takes exactly 60 seconds — I will time it. And if you do not see a difference, I will wish you a great day. Deal?"',textEs:'"Esto son exactamente 60 segundos — te los cronometro. Y si no ves diferencia, te deseo un buen día. ¿Trato?"'},{id:"p-two-seconds",category:"partner",title:"The one who is already walking",titleEs:"El que ya se está yendo",text:`"It's two seconds of your time, I promise — she's going to love it."`,textEs:'"Son dos segundos, te lo prometo — le va a encantar."'},{id:"p1",category:"partner",title:"1. Bring him in — this is the first move",titleEs:"1. Métele dentro — esta es la primera jugada",text:'"And you — you are going to love how this looks on them. Want to see the instant result too?" Get him laughing, get him looking, make him part of the reveal. A partner who is IN the demo does not pull her out of it.',textEs:'"Y tú — te va a encantar cómo le queda. ¿Quieres ver el resultado instantáneo tú también?" Que se ría, que mire, que sea parte de la revelación. Una pareja que está DENTRO de la demo no te la saca de ella.'},{id:"p3",category:"partner",title:"2. Opinion Ask",titleEs:"2. Pedir Opinión",text:'"What do you think — the instant glow or the long-term treatment? You know them best."',textEs:'"¿Tú qué crees — el brillo instantáneo o el tratamiento a largo plazo? Tú la conoces mejor."'},{id:"p-ladies",category:"partner",title:"3. Only if the energy is bad: stand him down",titleEs:"3. Solo si la energía es mala: apártale",text:`"Don't worry, it's ladies' business anyway." Say it light, with a smile — you are giving him permission to stand back, not picking a fight. This is your SECOND move, never your first.`,textEs:'"No te preocupes, esto es cosa de chicas de todas formas." Dilo ligero, con una sonrisa — le estás dando permiso para apartarse, no buscando pelea. Esta es tu SEGUNDA jugada, nunca la primera.'},{id:"p-let-go",category:"partner",title:"4. He is completely bad energy",titleEs:"4. Trae muy mala energía",text:"Stop spending anything on him and put ALL of it on her. Not a sulk, not a sigh — you simply turn your body, keep her hand in yours and carry on as if he were furniture. You have not lost him; you never had him.",textEs:"Deja de gastar nada en él y ponlo TODO en ella. Sin morros y sin suspiros — simplemente giras el cuerpo, no le sueltas la mano y sigues como si él fuera un mueble. No le has perdido; nunca le tuviste."},{id:"p2",category:"partner",title:"Gift Suggestion",titleEs:"Sugerencia de Regalo",text:`"Most couples take a Nail Kit for her and a Body Butter for him — a nice memory from {locationName}. And with buy 2 get 1 free the third one is on me: {currency}${r.price} for ${r.units}."`,textEs:`"La mayoría de las parejas se llevan un Kit de Uñas para ella y una Manteca Corporal para él — un bonito recuerdo de {locationName}. Y con compra 2 y llévate 1 gratis, el tercero te lo regalo: {currency}${r.price} por ${r.units}."`},{id:"comp1",category:"competitor",title:'"They said it is cheaper there"',titleEs:'"Me han dicho que allí es más barato"',text:'"Maybe! But does their product show you a result in 2 minutes? Let me show you..."',textEs:'"¡Puede ser! Pero ¿su producto te enseña un resultado en 2 minutos? Mira..."'},{id:"comp2",category:"competitor",title:'"I saw this on Amazon"',titleEs:'"Lo he visto en Amazon"',text:'"You probably did! But online you cannot try it. Feel this — smell this — see the result on your own skin."',textEs:'"¡Seguramente sí! Pero por internet no lo puedes probar. Toca esto — huele esto — mira el resultado en tu propia piel."'},{id:"comp3",category:"competitor",title:'"The other shop gave me a better price"',titleEs:'"La otra tienda me ha dado mejor precio"',text:'"Go on then — what did they say?" [Let them tell you] "Right. That price I cannot do, I would be working for nothing." [Pause] "But I will tell you what I CAN do…" — then move ONE rung and put something small in the bag.',textEs:'"Venga, cuéntame — ¿qué te han dicho?" [Deja que te lo cuente] "Ya. Ese precio no te lo puedo hacer, estaría trabajando gratis." [Pausa] "Pero te digo lo que SÍ puedo hacer…" — y bajas UN escalón y le metes algo pequeño en la bolsa.'},{id:"comp4",category:"competitor",title:'"I have heard of [competitor brand]"',titleEs:'"He oído hablar de [marca competidora]"',text:'"Great brand! We actually use similar ingredients. The difference is our concentration and the immediate result. Watch..."',textEs:'"¡Buena marca! De hecho usamos ingredientes parecidos. La diferencia es nuestra concentración y el resultado inmediato. Mira..."'}],F=[{id:"g1",type:"good",text:'"Let me show you something..."',textEs:'"Déjame enseñarte una cosa..."',reason:"Creates curiosity, no pressure",reasonEs:"Crea curiosidad, sin presión"},{id:"g2",type:"good",text:'"Most people choose..."',textEs:'"La mayoría se lleva..."',reason:"Nobody wants to be the only one",reasonEs:"Nadie quiere ser la única"},{id:"g3",type:"good",text:'"This is only valid today"',textEs:'"Esto solo vale hoy"',reason:"Puts a door on the price. Say it straight and move on",reasonEs:"Le pone una puerta al precio. Dilo sin más y sigue"},{id:"g4",type:"good",text:'"You will see the difference instantly"',textEs:'"Vas a ver la diferencia al instante"',reason:"Promises immediate value",reasonEs:"Promete valor inmediato"},{id:"g5",type:"good",text:'"What brings you to {locationName}?"',textEs:'"¿Qué te trae por {locationName}?"',reason:"Opens the conversation naturally",reasonEs:"Abre la conversación con naturalidad"},{id:"g6",type:"good",text:'"That is a great choice"',textEs:'"Es una gran elección"',reason:"Validates their decisión",reasonEs:"Valida su decisión"},{id:"g7",type:"good",text:'"Feel this texture..."',textEs:'"Toca esta textura..."',reason:"Hands first. Once they are touching it, it is half theirs",reasonEs:"Primero las manos. En cuanto lo tocan, ya es medio suyo"},{id:"g8",type:"good",text:'"Can I ask your opinion?"',textEs:'"¿Te puedo pedir tu opinión?"',reason:"Makes them feel valued",reasonEs:"Les hace sentir valorados"},{id:"b1",type:"bad",text:'"Do you need any help?"',textEs:'"¿Necesitas ayuda?"',reason:'Triggers the "just looking" reflex',reasonEs:'Dispara el reflejo de "solo estoy mirando"'},{id:"b2",type:"bad",text:'"It is really cheap"',textEs:'"Es muy barato"',reason:"Cheapens how the product is seen",reasonEs:"Devalúa la percepción del producto"},{id:"b3",type:"bad",text:'"No problem / Sure"',textEs:'"No hay problema / Vale"',reason:"Sounds like a waiter, not the person running this pitch",reasonEs:"Suena a camarero, no a quien lleva el puesto"},{id:"b4",type:"bad",text:'"Are you interested?"',textEs:'"¿Te interesa?"',reason:"Easy to say no to",reasonEs:"Muy fácil decir que no"},{id:"b5",type:"bad",text:'"Trust me..."',textEs:'"Confía en mí..."',reason:"Raises suspicion",reasonEs:"Genera sospecha"},{id:"b6",type:"bad",text:'"This is our most expensive"',textEs:'"Este es el más caro"',reason:"Focuses on cost, not value",reasonEs:"Se centra en el coste, no en el valor"}],Q=[{id:"ci1",name:"Give first",nameEs:"Da tú primero",description:"The little gift is not generosity, it is the hook. Once they have taken something off you, walking out feels rude.",descriptionEs:"El regalito no es generosidad, es el anzuelo. En cuanto te han cogido algo, irse sin más les da corte.",apply:`"You know what — just because you look so amazing, I'm going to give you a small gift. I think you're going to love it." Promise it out on the street to move them, hand it over once they are in the chair. Sample, demo, gift — all before you have asked them for anything at all.`,applyEs:'"¿Sabes qué? Solo porque estás guapísima, te voy a hacer un regalito. Creo que te va a encantar." Prométeselo en la calle para moverlos, dáselo ya sentados. Muestra, demo, regalo — todo antes de haberles pedido absolutamente nada.'},{id:"ci2",name:"Get the yes before the yes",nameEs:"El sí antes del sí",description:"Nobody likes going back on something they just said out loud.",descriptionEs:"A nadie le gusta desdecirse de algo que acaba de decir en voz alta.",apply:'Make them say it, do not say it for them: "Look at that — better, right?" Once they have said better, no is awkward.',applyEs:'Que lo digan ellas, no lo digas tú: "Mira eso — mejor, ¿a que sí?" Cuando ya han dicho que mejor, decir que no queda raro.'},{id:"ci3",name:"Everybody is taking it",nameEs:"Todo el mundo se lo lleva",description:"Nobody wants to be the only one. Deciding is easier when other people already did.",descriptionEs:"Nadie quiere ser la única. Decidirse es más fácil cuando ya lo ha hecho otra gente.",apply:'"That is the one everybody takes." / "I have sold three of those this morning." Say it like it is nothing — throw it away and carry on.',applyEs:'"Ese es el que se lleva todo el mundo." / "Llevo tres vendidos esta mañana." Dilo como si nada — suéltalo y sigue.'},{id:"ci4",name:"You do this all day",nameEs:"Tú haces esto todo el día",description:"They believe the person who has obviously done it a thousand times. On a kiosk that is you — volume and hands, nothing borrowed.",descriptionEs:"Se fían de quien se ve que lo ha hecho mil veces. En un puesto esa eres tú — cantidad y manos, nada prestado.",apply:'"I have done this on about forty faces today — I know exactly how it goes on skin like yours." Your hands are the proof. No borrowed white coats.',applyEs:'"Hoy llevo unas cuarenta caras — sé perfectamente cómo queda en una piel como la tuya." Tus manos son la prueba. Sin batas blancas prestadas.'},{id:"ci5",name:"They buy you first",nameEs:"Primero te compran a ti",description:"Nobody buys hand cream off someone they are trying to get away from.",descriptionEs:"Nadie le compra crema de manos a alguien de quien está intentando escaparse.",apply:"Say the nice thing and mean it, find the one thing you have in common, match their speed — quick with the rushers, slow with the strollers.",applyEs:"Di lo bonito y créetelo, busca eso que tenéis en común, ponte a su ritmo — rápido con los que van con prisa, tranquilo con los que pasean."},{id:"ci6",name:"Today or never",nameEs:"Hoy o nunca",description:"A price with no end on it is not a price, it is a shelf. Put a door on it.",descriptionEs:"Un precio sin final no es un precio, es una estantería. Ponle una puerta.",apply:'"Only today." / "Two left." / "This voucher dies the second you walk out of here." Straight face, half a smile — and drop it the moment they say no.',applyEs:'"Solo hoy." / "Me quedan dos." / "Este cupón se muere en cuanto sales por esa puerta." Cara seria, media sonrisa — y lo sueltas en cuanto te digan que no.'}],K=[{id:"bl1",term:"Open palms when presenting",termEs:"Palmas abiertas al presentar",meaning:"Nothing hidden, nothing up the sleeve",meaningEs:"Nada escondido, nada en la manga"},{id:"bl2",term:"Slight forward lean",termEs:"Inclínate ligeramente hacia delante",meaning:"Says you are interested in her, not just her money",meaningEs:"Dice que te interesa ella, no solo su dinero"},{id:"bl3",term:"Mirror their posture",termEs:"Imita su postura",meaning:"They relax and never know why",meaningEs:"Se relajan y no saben por qué"},{id:"bl4",term:"Smile like you mean it",termEs:"Sonríe como si lo sintieras",meaning:"A mouth-only smile reads as a salesman. Smile with the eyes or do not bother",meaningEs:"La sonrisa de solo boca suena a vendedor. Sonríe con los ojos o no sonrías"},{id:"bl5",term:"Put the product in their hand",termEs:"Ponles el producto en la mano",meaning:"Once they hold it, ownership starts",meaningEs:"En cuanto lo sostienen, empieza la sensación de propiedad"},{id:"bl6",term:"Come at them a bit from the side",termEs:"Acércate un poco de lado",meaning:"Nobody likes a stranger squared up in their face. Angled, never blocking the way",meaningEs:"A nadie le gusta un desconocido plantado en la cara. De lado, y sin cortarle el paso"}],X=[{id:"bs1",term:"Asks about the price",termEs:"Pregunta el precio",meaning:"Seriously considering the purchase",meaningEs:"Se está planteando la compra en serio"},{id:"bs2",term:"Touches or holds the product",termEs:"Toca o sostiene el producto",meaning:"Imagining owning it",meaningEs:"Se imagina teniéndolo"},{id:"bs3",term:'Asks "how long does it last?"',termEs:'Pregunta "¿cuánto dura?"',meaning:"Calculating the value",meaningEs:"Está calculando el valor"},{id:"bs4",term:"Looks at their partner or friend",termEs:"Mira a su pareja o amiga",meaning:"Looking for permission to buy",meaningEs:"Busca permiso para comprar"},{id:"bs5",term:"Repeats the benefit back to you",termEs:"Te repite el beneficio",meaning:"Mental buy-in is forming",meaningEs:"Se está convenciendo por dentro"},{id:"bs6",term:'Asks "can I use this with...?"',termEs:'Pregunta "¿esto lo puedo usar con...?"',meaning:"Fitting it into their life",meaningEs:"Lo está encajando en su vida"}],M=[{id:"eo1",text:'"I promise this will be the best 2 minutes of your day"',textEs:'"Te prometo que van a ser los mejores 2 minutos de tu día"'},{id:"eo2",text:'"I just want to show you something amazing — no pressure to buy"',textEs:'"Solo quiero enseñarte algo increíble — sin ningún compromiso"'},{id:"eo3",text:'"Everyone who tries this buys it — want to see why?"',textEs:'"Todo el que lo prueba se lo lleva — ¿quieres ver por qué?"'},{id:"eo4",text:'"Can I ask you a quick question? What do you use for your eyes?"',textEs:'"¿Te hago una pregunta rápida? ¿Qué usas para el contorno de ojos?"'},{id:"eo5",text:'"Watch this — I guarantee you have never seen anything like it"',textEs:'"Mira esto — te garantizo que nunca has visto nada igual"'}],R=[{id:"ec1",text:`"The voucher, then. {currency}${c.price} instead of {currency}${t.price} — today, and only while you are stood in front of me"`,textEs:`"Pues el cupón. {currency}${c.price} en vez de {currency}${t.price} — hoy, y solo mientras estés aquí delante de mí"`},{id:"ec2",text:`"Take a second one for your friend, your mum, your sister — buy 2 and the third is free, {currency}${r.price} for ${r.units}"`,textEs:`"Llévate otro para tu amiga, tu madre, tu hermana — compra 2 y el tercero es gratis, {currency}${r.price} por ${r.units}"`},{id:"ec3",text:`"Right — you are killing me. Go on, give me your number." [Let them say it. Hold. Then hands in the air] "You are not talking to the right man. Give me ten seconds." Then go and get the manager — he is the only one who can say {currency}${b.price}, and it lands ten times harder from him than it ever would from you.`,textEs:`"Venga — me estás matando. Dime tu número." [Deja que lo digan. Aguanta. Luego manos arriba] "No estás hablando con quien tienes que hablar. Dame diez segundos." Y vas a por el encargado — es el único que puede decir {currency}${b.price}, y de su boca cae diez veces más fuerte que de la tuya.`}],z=[{id:"ek1",answers:"price",head:'"Too expensive"',headEs:'"Muy caro"',text:`"Compared to what, my love? One session of Botox back home is {currency}${p} and it wears off by Christmas. You are at {currency}${c.price} with me — voucher on, gift off, a whole year in that syringe." [Still not moving, and she is genuinely walking? You have no rung left. Do NOT invent one] "Sit tight one second — let me get someone." Then fetch the manager, and {currency}${b.price} comes out of his mouth.`,textEs:`"¿Comparado con qué, cariño? Una sesión de Bótox en tu país son {currency}${p} y se te pasa para Navidad. Conmigo estás en {currency}${c.price} — con el cupón, sin regalo, un año entero en esa jeringa." [¿Sigue sin moverse y se va de verdad? No te queda escalón. NO te inventes uno] "Espérate un segundo, que llamo a alguien." Vas a por el encargado, y {currency}${b.price} sale de su boca.`},{id:"ek2",answers:"think",head:'"I need to think"',headEs:'"Tengo que pensármelo"',text:`"I get it. But this price is literally today only — tomorrow it is back to {currency}${u}."`,textEs:`"Lo entiendo. Pero este precio es literalmente solo de hoy — mañana vuelve a {currency}${u}."`},{id:"ek3",answers:"looking",head:'"Just looking"',headEs:'"Solo estoy mirando"',text:'"Perfect! Looking is free. But trying is what changes your mind. Two minutes?"',textEs:'"¡Perfecto! Mirar es gratis. Pero probarlo es lo que te cambia la cabeza. ¿Dos minutos?"'}],B=[{id:"ect1",head:"Declined",headEs:"Rechazada",text:'"No problem at all — do you have another card on you?"',textEs:'"No pasa nada — ¿llevas otra tarjeta encima?"'},{id:"ect2",head:"Declined again",headEs:"Rechazada otra vez",text:'"Let me try typing the numbers in by hand — the chip does this sometimes."',textEs:'"Déjame probar metiendo los números a mano — el chip hace esto a veces."'},{id:"ect3",head:"No other card",headEs:"No tiene otra tarjeta",text:'"Have you got Apple Pay or Google Pay on your phone? That works too."',textEs:'"¿Tienes Apple Pay o Google Pay en el móvil? Eso también nos vale."'},{id:"ect4",head:"No card at all",headEs:"Sin tarjeta",text:`"Cash suits me even better, my love. There's a machine two minutes that way — I'll walk you over and carry the bag." You go WITH them. You never send them off on their own.`,textEs:'"En efectivo aún mejor, cariño. Hay un cajero a dos minutos — te acompaño yo y te llevo la bolsa." Vas CON ellos. Nunca los mandas solos.'}],_=[{key:"openers",accent:"coral",numbered:!0,title:"Emergency Openers",titleEs:"Aperturas de Emergencia",hint:"When nothing else is working:",hintEs:"Cuando nada más funciona:",items:M},{key:"closes",accent:"teal",title:"Emergency Closes",titleEs:"Cierres de Emergencia",hint:"Last resort to close:",hintEs:"Último recurso para cerrar:",items:R},{key:"killers",accent:"gold",title:"Objection Killers",titleEs:"Matadores de Objeciones",hint:"Quick answers to the usual objections:",hintEs:"Respuestas rápidas a las objeciones de siempre:",items:z},{key:"card",accent:"violet",title:"Card trouble",titleEs:"Problemas con la tarjeta",hint:"Work down the list. Stay relaxed — they are already embarrassed:",hintEs:"Ve bajando por la lista. Mantén la calma — ya están incómodos:",items:B}];function J(e){const d=[];for(const n of L){if(n.answers!==e)continue;const h=n.product?Y[n.product]:void 0;d.push({key:`s-${n.id}`,label:h?.short,labelEs:h?.shortEs,text:n.text,textEs:n.textEs})}for(const n of _)for(const h of n.items)h.answers===e&&d.push({key:`e-${h.id}`,label:"Under pressure",labelEs:"Bajo presión",text:h.text,textEs:h.textEs});return d}export{W as A,K as B,Q as C,_ as E,Y as L,F as P,L as S,X as a,C as b,J as l,V as p,H as t};
